<!DOCTYPE html>
<html lang="vi">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="csrf-token" content="{{ csrf_token() }}">
    <title>Hàng về PANEL</title>
    <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet">
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
    <style>
        :root{--blue:#2563eb;--blue-dark:#15366d;--blue-soft:#eaf4ff;--line:#c7d7ee;--ink:#0f172a;--muted:#64748b;--bg:#f5faff;--good:#15803d;--danger:#b91c1c}
        *{box-sizing:border-box}body{min-height:100vh;margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif}.receipt-shell{width:min(1500px,calc(100% - 28px));margin:auto;padding:12px 0 28px}.receipt-header,.receipt-panel{border:1px solid #dbeafe;border-radius:8px;background:#fff;box-shadow:0 10px 26px rgba(37,99,235,.07)}.receipt-header{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px;padding:12px 14px}.receipt-title{margin:0;color:var(--blue-dark);font-size:24px;font-weight:800}.receipt-sub{margin:3px 0 0;color:var(--muted);font-size:13px}.receipt-actions,.panel-actions{display:flex;align-items:center;flex-wrap:wrap;gap:8px}.quick-btn{min-height:40px;display:inline-flex;align-items:center;justify-content:center;gap:7px;padding:0 14px;border:1px solid var(--line);border-radius:8px;background:#fff;color:var(--blue-dark);font-weight:750;text-decoration:none;cursor:pointer}.quick-btn:hover,.quick-btn:focus-visible{border-color:#93c5fd;background:var(--blue-soft);color:var(--blue)}.quick-btn svg{width:17px;height:17px}.quick-btn-primary{border-color:var(--blue);background:var(--blue);color:#fff}.quick-btn-primary:hover{background:#1d4ed8;color:#fff}.quick-btn:disabled{cursor:wait;opacity:.6}.receipt-panel{overflow:visible;margin-bottom:12px}.panel-head{display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:49px;padding:10px 14px;border-bottom:1px solid #e2e8f0}.panel-head h2{margin:0;color:var(--blue-dark);font-size:15px;font-weight:800}.receipt-meta{display:grid;grid-template-columns:180px minmax(260px,1fr) auto;gap:10px;padding:12px 14px}.field label{display:block;margin-bottom:5px;color:#334155;font-size:12px;font-weight:700}.form-control{min-height:40px;border-color:var(--line);border-radius:7px}.form-control:focus{border-color:#60a5fa;box-shadow:0 0 0 3px rgba(37,99,235,.12)}.search-wrap{position:relative;padding:12px 14px}.search-box{position:relative}.search-box svg{position:absolute;left:13px;top:50%;width:19px;transform:translateY(-50%);color:var(--blue)}.search-box input{height:48px;padding-left:42px;font-size:16px;font-weight:650}.order-results{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:10px}.order-card{min-width:0;padding:12px;border:1px solid #cfe0f5;border-radius:8px;background:#f9fcff}.order-card__top{display:flex;align-items:start;justify-content:space-between;gap:8px}.order-card__ps{color:var(--blue);font-size:13px;font-weight:800}.order-card__panel{margin:7px 0 4px;color:var(--blue-dark);font-size:20px;font-weight:800;overflow-wrap:anywhere}.order-card__meta{min-height:38px;color:var(--muted);font-size:12px}.order-card__stats{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin:9px 0}.order-card__stats div{padding:6px;border-radius:6px;background:#fff;color:var(--muted);font-size:10px}.order-card__stats strong{display:block;color:var(--ink);font-size:13px}.order-card__entry{display:grid;grid-template-columns:1fr auto;gap:7px}.sheet-badge{padding:4px 7px;border-radius:999px;background:#dbeafe;color:#1e40af;font-size:10px;font-weight:800}.draft-table{width:100%;min-width:940px;border-collapse:collapse;font-size:13px}.table-wrap{width:100%;overflow:auto}.draft-table th{padding:9px 10px;background:#0f2f54;color:#fff;font-size:11px;text-transform:uppercase;white-space:nowrap}.draft-table td{padding:8px 10px;border-bottom:1px solid #e2e8f0;vertical-align:middle}.draft-table input{min-width:105px}.empty{padding:28px!important;color:var(--muted);text-align:center}.draft-total{display:flex;align-items:center;justify-content:flex-end;gap:20px;padding:10px 14px;border-top:1px solid #e2e8f0;color:var(--muted);font-size:12px}.draft-total strong{color:var(--blue-dark);font-size:18px}.status{display:none;margin-bottom:12px;padding:11px 13px;border:1px solid #bbf7d0;border-radius:7px;background:#f0fdf4;color:#166534;font-weight:650}.status.is-error{border-color:#fecaca;background:#fef2f2;color:#991b1b}.status.is-warning{border-color:#fde68a;background:#fffbeb;color:#92400e}.history-filter{display:grid;grid-template-columns:1fr 170px 170px auto;gap:9px;padding:10px 14px}.history-table{width:100%;min-width:820px;border-collapse:collapse;font-size:13px}.history-table th{padding:9px 11px;background:#0f2f54;color:#fff;font-size:11px;text-transform:uppercase}.history-table td{padding:9px 11px;border-bottom:1px solid #e2e8f0}.receipt-loader{position:fixed;inset:0;z-index:2000;display:grid;place-items:center;background:rgba(245,250,255,.78);backdrop-filter:blur(3px)}.receipt-loader[hidden]{display:none}.loader-box{min-width:260px;padding:22px;border:1px solid #cfe0f5;border-radius:8px;background:#fff;text-align:center;box-shadow:0 18px 48px rgba(25,70,120,.16)}.import-errors{max-height:150px;overflow:auto;font-size:12px}.modal-line{display:grid;grid-template-columns:1fr 1fr 1.2fr .8fr;gap:8px;padding:9px 0;border-bottom:1px solid #e2e8f0}.modal-line small{display:block;color:var(--muted)}
        html,body{max-width:100%;overflow-x:hidden}.receipt-header,.receipt-panel,.receipt-actions,.panel-actions,.quick-btn{min-width:0}.quick-btn svg{flex:0 0 auto}.table-wrap{width:100%;max-width:100%;min-width:0;overflow-x:auto;-webkit-overflow-scrolling:touch}
        @media(max-width:991.98px){.order-results{grid-template-columns:1fr 1fr}.receipt-meta,.history-filter{grid-template-columns:1fr 1fr}.receipt-meta .panel-actions{grid-column:1/-1}.history-filter .quick-btn{align-self:end}}@media(max-width:575.98px){.receipt-shell{width:calc(100% - 16px);padding-top:8px}.receipt-header{align-items:flex-start;flex-direction:column}.receipt-actions{display:grid;width:100%;grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.receipt-actions .quick-btn{width:100%;padding:0 8px;font-size:13px}.receipt-title{font-size:21px}.receipt-meta,.history-filter,.order-results{grid-template-columns:1fr}.receipt-meta .panel-actions{grid-column:auto}.panel-head{align-items:flex-start;flex-direction:column}.panel-actions{display:grid;width:100%;grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.panel-actions .quick-btn{width:100%;padding:0 8px}.modal-line{grid-template-columns:1fr 1fr}}
    </style>
</head>
<body>
<main class="receipt-shell">
    <header class="receipt-header">
        <div><h1 class="receipt-title">Hàng về PANEL</h1><p class="receipt-sub">Tìm PS, chọn PANEL và ghi số lượng thực nhận.</p></div>
        <div class="receipt-actions"><a class="quick-btn" href="{{ url('/client/don-hang-noi-bo') }}"><i data-lucide="database"></i>Đơn hàng A/B</a><a class="quick-btn" href="{{ route('panel-normalizations.page') }}"><i data-lucide="settings-2"></i>PANEL chuẩn</a></div>
    </header>
    <div id="statusBar" class="status" role="status"></div>

    <section class="receipt-panel">
        <div class="panel-head"><h2>Phiếu hàng về</h2><div class="panel-actions"><input id="importFile" type="file" class="d-none" accept=".xlsx,.xls,.csv"><button id="importBtn" class="quick-btn" type="button"><i data-lucide="file-up"></i>Import list</button><button id="saveBtn" class="quick-btn quick-btn-primary" type="button"><i data-lucide="printer"></i>Lưu + in</button></div></div>
        <div class="receipt-meta"><div class="field"><label for="receivedDate">Ngày hàng về</label><input id="receivedDate" class="form-control" inputmode="numeric" placeholder="dd/mm/yyyy"></div><div class="field"><label for="receiptNote">Ghi chú phiếu</label><input id="receiptNote" class="form-control" placeholder="Ca nhận, người giao hoặc ghi chú chung"></div><div class="d-flex align-items-end"><button id="clearBtn" class="quick-btn w-100" type="button"><i data-lucide="rotate-ccw"></i>Phiếu mới</button></div></div>
    </section>

    <section class="receipt-panel">
        <div class="panel-head"><h2>Chọn hàng theo PS</h2><span id="searchCount" class="small text-secondary">Gõ ít nhất 2 ký tự</span></div>
        <div class="search-wrap"><div class="search-box"><i data-lucide="search"></i><input id="psSearch" class="form-control" autocomplete="off" placeholder="Gõ PS hoặc mã hàng..."></div><div id="orderResults" class="order-results"></div></div>
    </section>

    <section class="receipt-panel">
        <div class="panel-head"><h2>Danh sách đang nhập</h2><span id="draftCount" class="small text-secondary">0 dòng</span></div>
        <div id="importErrors" class="import-errors d-none mx-3 mt-3 alert alert-warning"></div>
        <div class="table-wrap"><table class="draft-table"><thead><tr><th>PS</th><th>Mã hàng</th><th>PANEL</th><th>Size / màu</th><th>SL đơn</th><th>Đã nhận</th><th>SL về</th><th>Ghi chú</th><th></th></tr></thead><tbody id="draftRows"><tr><td colspan="9" class="empty">Chưa chọn PANEL.</td></tr></tbody></table></div>
        <div class="draft-total"><span>Tổng phiếu</span><strong id="draftTotal">0</strong></div>
    </section>

    <section class="receipt-panel">
        <div class="panel-head"><h2>Danh sách phiếu hàng về</h2><span id="historyCount" class="small text-secondary">Đang tải...</span></div>
        <div class="history-filter"><input id="historyKeyword" class="form-control" placeholder="Tìm số phiếu, PS, mã hàng hoặc PANEL"><input id="historyFrom" class="form-control" placeholder="Từ ngày dd/mm/yyyy"><input id="historyTo" class="form-control" placeholder="Đến ngày dd/mm/yyyy"><button id="historyReload" class="quick-btn" type="button"><i data-lucide="refresh-cw"></i>Tải lại</button></div>
        <div class="table-wrap"><table class="history-table"><thead><tr><th>Số phiếu</th><th>Ngày</th><th>Nguồn</th><th>Dòng</th><th>Tổng SL</th><th>Ghi chú</th><th>Thao tác</th></tr></thead><tbody id="historyRows"><tr><td colspan="7" class="empty">Đang tải...</td></tr></tbody></table></div>
        <div class="d-flex justify-content-between align-items-center p-3 border-top"><button id="historyPrev" class="quick-btn" type="button">Trước</button><span id="historyPage" class="small text-secondary"></span><button id="historyNext" class="quick-btn" type="button">Sau</button></div>
    </section>
</main>

<div class="modal fade" id="detailModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-lg modal-dialog-centered modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><div><h2 id="detailTitle" class="modal-title fs-5"></h2><div id="detailSub" class="small text-secondary"></div></div><button class="btn-close" data-bs-dismiss="modal" aria-label="Đóng"></button></div><div id="detailBody" class="modal-body"></div><div class="modal-footer justify-content-between"><button id="deleteReceipt" class="btn btn-outline-danger" type="button">Xóa phiếu</button><a id="printReceipt" class="quick-btn quick-btn-primary" target="_blank"><i data-lucide="printer"></i>In phiếu</a></div></div></div></div>
<div id="loader" class="receipt-loader" hidden><div class="loader-box"><div class="spinner-border text-primary"></div><div id="loaderText" class="fw-bold mt-3">Đang xử lý...</div></div></div>

<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>
<script src="https://unpkg.com/lucide@latest"></script>
<script>
(() => {
    const csrf=document.querySelector('meta[name="csrf-token"]').content;
    const state={draft:[],searchTimer:null,controller:null,historyPage:1,historyLast:1,detailId:null,deleteArmed:false,sourceFile:null};
    const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
    const num=v=>Number(v||0).toLocaleString('vi-VN',{maximumFractionDigits:3});
    const json=async(r,fallback)=>{const body=await r.json().catch(()=>({}));if(!r.ok)throw new Error(Object.values(body.errors||{}).flat()[0]||body.message||fallback);return body};
    const iso=value=>{const match=String(value||'').trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);if(!match)return null;const d=Number(match[1]),m=Number(match[2]),y=Number(match[3]);const date=new Date(y,m-1,d);return date.getFullYear()===y&&date.getMonth()===m-1&&date.getDate()===d?`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`:null};
    const viDate=value=>{const date=value?new Date(value+'T00:00:00'):new Date();return `${String(date.getDate()).padStart(2,'0')}/${String(date.getMonth()+1).padStart(2,'0')}/${date.getFullYear()}`};
    const notify=(message,type='success')=>{const bar=document.getElementById('statusBar');bar.textContent=message;bar.className=`status${type==='error'?' is-error':type==='warning'?' is-warning':''}`;bar.style.display='block';if(type==='success')setTimeout(()=>bar.style.display='none',5000)};
    const busy=(on,text='Đang xử lý...')=>{document.getElementById('loader').hidden=!on;document.getElementById('loaderText').textContent=text};
    document.getElementById('receivedDate').value=viDate();

    function renderSearch(rows){
        document.getElementById('searchCount').textContent=`${num(rows.length)} lựa chọn`;
        document.getElementById('orderResults').innerHTML=rows.map(row=>`<article class="order-card" data-order='${esc(JSON.stringify(row))}'><div class="order-card__top"><span class="order-card__ps">${esc(row.ps_number||'-')}</span><span class="sheet-badge">${esc(row.sheet_code||'-')}</span></div><div class="order-card__panel">${esc(row.panel||'CHƯA CÓ PANEL')}</div><div class="order-card__meta"><strong>${esc(row.item_code||'-')}</strong><br>${esc([row.size,row.fabric_color,row.logo_color].filter(Boolean).join(' · ')||'-')}</div><div class="order-card__stats"><div>Đơn<strong>${num(row.order_quantity)}</strong></div><div>Đã nhận<strong>${num(row.received_quantity)}</strong></div><div>Còn<strong>${num(row.remaining_quantity)}</strong></div></div><div class="order-card__entry"><input class="form-control card-qty" type="number" min="0.001" step="0.001" value="${Number(row.remaining_quantity)>0?Number(row.remaining_quantity):''}" placeholder="Số lượng"><button class="quick-btn quick-btn-primary add-card" type="button"><i data-lucide="plus"></i>Thêm</button></div></article>`).join('')||'<div class="empty grid-column-full">Không tìm thấy PS phù hợp trong Đơn hàng A/B.</div>';
        lucide.createIcons();
    }

    async function search(){const keyword=document.getElementById('psSearch').value.trim();if(keyword.length<2){document.getElementById('orderResults').innerHTML='';document.getElementById('searchCount').textContent='Gõ ít nhất 2 ký tự';return}state.controller?.abort();state.controller=new AbortController();try{const result=await fetch(`/api/hang-ve-panel/tim-don?keyword=${encodeURIComponent(keyword)}&limit=60`,{signal:state.controller.signal}).then(r=>json(r,'Không tìm được PS'));renderSearch(result.data||[])}catch(error){if(error.name!=='AbortError')notify(error.message,'error')}}
    document.getElementById('psSearch').addEventListener('input',()=>{clearTimeout(state.searchTimer);state.searchTimer=setTimeout(search,220)});
    document.getElementById('orderResults').addEventListener('click',event=>{const button=event.target.closest('.add-card');if(!button)return;const card=button.closest('.order-card');const row=JSON.parse(card.dataset.order);const quantity=Number(card.querySelector('.card-qty').value);if(!(quantity>0)){notify('Nhập số lượng hàng về lớn hơn 0.','warning');return}state.draft.push({...row,client_key:`${row.id}-${Date.now()}-${Math.random()}`,received_quantity_input:quantity,note:''});renderDraft()});

    function renderDraft(){const body=document.getElementById('draftRows');body.innerHTML=state.draft.map((row,index)=>`<tr data-key="${esc(row.client_key)}"><td><strong>${esc(row.ps_number||'-')}</strong></td><td>${esc(row.item_code||'-')}</td><td><strong>${esc(row.panel||'-')}</strong></td><td>${esc([row.size,row.fabric_color].filter(Boolean).join(' · ')||'-')}</td><td>${num(row.order_quantity)}</td><td>${num(row.received_quantity)}</td><td><input class="form-control draft-qty" type="number" min="0.001" step="0.001" value="${row.received_quantity_input}"></td><td><input class="form-control draft-note" value="${esc(row.note||'')}" placeholder="Ghi chú"></td><td><button class="btn btn-sm btn-outline-danger remove-line" type="button" aria-label="Xóa dòng"><i data-lucide="x"></i></button></td></tr>`).join('')||'<tr><td colspan="9" class="empty">Chưa chọn PANEL.</td></tr>';document.getElementById('draftCount').textContent=`${num(state.draft.length)} dòng`;document.getElementById('draftTotal').textContent=num(state.draft.reduce((sum,row)=>sum+Number(row.received_quantity_input||0),0));lucide.createIcons()}
    document.getElementById('draftRows').addEventListener('input',event=>{const tr=event.target.closest('tr');const row=state.draft.find(item=>item.client_key===tr?.dataset.key);if(!row)return;if(event.target.classList.contains('draft-qty'))row.received_quantity_input=Number(event.target.value);if(event.target.classList.contains('draft-note'))row.note=event.target.value;document.getElementById('draftTotal').textContent=num(state.draft.reduce((sum,item)=>sum+Number(item.received_quantity_input||0),0))});
    document.getElementById('draftRows').addEventListener('click',event=>{const button=event.target.closest('.remove-line');if(!button)return;const key=button.closest('tr').dataset.key;state.draft=state.draft.filter(row=>row.client_key!==key);renderDraft()});

    document.getElementById('importBtn').addEventListener('click',()=>document.getElementById('importFile').click());
    document.getElementById('importFile').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;const form=new FormData();form.append('file',file);busy(true,'Đang đối chiếu PS và PANEL...');try{const result=await fetch('/api/hang-ve-panel/import-preview',{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':csrf},body:form}).then(r=>json(r,'Không đọc được file hàng về'));state.sourceFile=result.file_name;(result.data||[]).forEach((row,index)=>state.draft.push({...row,client_key:`import-${Date.now()}-${index}`,received_quantity_input:row.received_quantity_input,note:''}));const errors=result.errors||[];const box=document.getElementById('importErrors');box.classList.toggle('d-none',!errors.length);box.innerHTML=errors.length?`<strong>${errors.length} dòng chưa đưa vào phiếu:</strong><br>${errors.slice(0,30).map(e=>`${esc(e.sheet)} dòng ${e.row}: ${esc(e.message)}`).join('<br>')}`:'';renderDraft();notify(`Đã đối chiếu ${result.summary.matched_rows} dòng, ${result.summary.error_rows} dòng cần kiểm tra.`,errors.length?'warning':'success')}catch(error){notify(error.message,'error')}finally{busy(false);event.target.value=''}});

    async function save(){const receivedDate=iso(document.getElementById('receivedDate').value);if(!receivedDate){notify('Ngày hàng về phải đúng định dạng dd/mm/yyyy.','warning');return}if(!state.draft.length){notify('Chưa có dòng hàng về.','warning');return}if(state.draft.some(row=>!(Number(row.received_quantity_input)>0))){notify('Mọi dòng phải có số lượng lớn hơn 0.','warning');return}busy(true,'Đang lưu phiếu hàng về...');try{const result=await fetch('/api/hang-ve-panel',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({received_date:receivedDate,source_type:state.sourceFile?'IMPORT':'MANUAL',source_file_name:state.sourceFile,note:document.getElementById('receiptNote').value,lines:state.draft.map(row=>({order_tracking_row_id:row.id,received_quantity:row.received_quantity_input,note:row.note||null,source_row:row.source_row||null}))})}).then(r=>json(r,'Không lưu được phiếu hàng về'));notify(result.message);window.open(result.print_url,'_blank');clearForm();loadHistory(1);search()}catch(error){notify(error.message,'error')}finally{busy(false)}}
    document.getElementById('saveBtn').addEventListener('click',save);
    function clearForm(){state.draft=[];state.sourceFile=null;document.getElementById('receiptNote').value='';document.getElementById('importErrors').classList.add('d-none');renderDraft()}
    document.getElementById('clearBtn').addEventListener('click',clearForm);

    async function loadHistory(page=1){state.historyPage=page;const params=new URLSearchParams({page,per_page:15});const keyword=document.getElementById('historyKeyword').value.trim();if(keyword)params.set('keyword',keyword);const from=iso(document.getElementById('historyFrom').value);const to=iso(document.getElementById('historyTo').value);if(from)params.set('date_from',from);if(to)params.set('date_to',to);const body=document.getElementById('historyRows');body.innerHTML='<tr><td colspan="7" class="empty">Đang tải...</td></tr>';try{const result=await fetch(`/api/hang-ve-panel?${params}`).then(r=>json(r,'Không tải được danh sách phiếu'));state.historyLast=Number(result.meta.last_page||1);document.getElementById('historyCount').textContent=`${num(result.meta.total)} phiếu`;document.getElementById('historyPage').textContent=`Trang ${result.meta.current_page||1}/${state.historyLast}`;document.getElementById('historyPrev').disabled=page<=1;document.getElementById('historyNext').disabled=page>=state.historyLast;body.innerHTML=(result.data||[]).map(row=>`<tr><td><strong>${esc(row.receipt_number)}</strong></td><td>${esc(row.received_date_label)}</td><td>${row.source_type==='IMPORT'?'Import':'Nhập tay'}${row.source_file_name?`<small class="d-block text-secondary">${esc(row.source_file_name)}</small>`:''}</td><td>${num(row.line_count)}</td><td><strong>${num(row.total_quantity)}</strong></td><td>${esc(row.note||'-')}</td><td><div class="d-flex gap-1"><button class="btn btn-sm btn-outline-primary view-receipt" data-id="${row.id}">Xem</button><a class="btn btn-sm btn-outline-secondary" target="_blank" href="${esc(row.print_url)}">In</a></div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Chưa có phiếu hàng về.</td></tr>'}catch(error){body.innerHTML=`<tr><td colspan="7" class="empty text-danger">${esc(error.message)}</td></tr>`}}
    let historyTimer;document.getElementById('historyKeyword').addEventListener('input',()=>{clearTimeout(historyTimer);historyTimer=setTimeout(()=>loadHistory(1),300)});document.getElementById('historyReload').addEventListener('click',()=>loadHistory(1));document.getElementById('historyPrev').addEventListener('click',()=>state.historyPage>1&&loadHistory(state.historyPage-1));document.getElementById('historyNext').addEventListener('click',()=>state.historyPage<state.historyLast&&loadHistory(state.historyPage+1));
    const modal=new bootstrap.Modal(document.getElementById('detailModal'));document.getElementById('historyRows').addEventListener('click',async event=>{const button=event.target.closest('.view-receipt');if(!button)return;state.detailId=button.dataset.id;state.deleteArmed=false;document.getElementById('deleteReceipt').textContent='Xóa phiếu';document.getElementById('deleteReceipt').className='btn btn-outline-danger';busy(true,'Đang tải phiếu...');try{const result=await fetch(`/api/hang-ve-panel/${state.detailId}`).then(r=>json(r,'Không tải được phiếu'));document.getElementById('detailTitle').textContent=result.data.receipt_number;document.getElementById('detailSub').textContent=`${result.data.received_date_label} · ${num(result.data.line_count)} dòng · ${num(result.data.total_quantity)}`;document.getElementById('printReceipt').href=result.data.print_url;document.getElementById('detailBody').innerHTML=(result.lines||[]).map(line=>`<div class="modal-line"><div><small>PS</small><strong>${esc(line.ps_number)}</strong></div><div><small>PANEL</small><strong>${esc(line.panel||'-')}</strong></div><div><small>Mã / màu</small>${esc(line.item_code||'-')}<br><span class="text-secondary">${esc([line.size,line.fabric_color].filter(Boolean).join(' · '))}</span></div><div><small>Số lượng</small><strong>${num(line.received_quantity)}</strong></div></div>`).join('');modal.show();lucide.createIcons()}catch(error){notify(error.message,'error')}finally{busy(false)}});
    document.getElementById('deleteReceipt').addEventListener('click',async event=>{if(!state.deleteArmed){state.deleteArmed=true;event.currentTarget.textContent='Bấm lại để xác nhận';event.currentTarget.className='btn btn-danger';return}event.currentTarget.disabled=true;try{const result=await fetch(`/api/hang-ve-panel/${state.detailId}`,{method:'DELETE',headers:{Accept:'application/json','X-CSRF-TOKEN':csrf}}).then(r=>json(r,'Không xóa được phiếu'));modal.hide();notify(result.message);loadHistory(1);search()}catch(error){notify(error.message,'error')}finally{event.currentTarget.disabled=false}});
    loadHistory();renderDraft();lucide.createIcons();
})();
</script>
</body>
</html>
